'use client';
import { useState } from 'react';
import { ImagePlus, Pencil, Plus, Trash2, X } from 'lucide-react';
import { API, Product } from '@/lib/api';

const blank = { name: '', slug: '', price: 0, category: 'oversized', inventory: 0, published: true, colorName: 'Jet Black', colorHex: '#0b0b0b', colorsText: 'Jet Black|#0b0b0b', sizesText: 'S, M, L, XL, 2XL', imagesText: '', tagsText: 'new', fabric: 'Heavyweight cotton', detailsText: 'Premium quality' };
const prepare = (p: any) => ({ ...p, colorsText: (p.colors?.length ? p.colors : [{ name: p.colorName, hex: p.colorHex }]).map((c: any) => `${c.name}|${c.hex}`).join('\n'), sizesText: (p.sizes || ['S','M','L','XL','2XL']).join(', '), imagesText: (p.images || []).join('\n'), tagsText: (p.tags || []).join(', '), detailsText: (p.details || []).join('\n') });

export default function ProductManager({ initial }: { initial: Product[] }) {
  const [items, setItems] = useState<any[]>(initial); const [editing, setEditing] = useState<any | null>(null); const [error, setError] = useState(''); const [uploading, setUploading] = useState(false);
  const set = (key: string, value: any) => setEditing((current: any) => ({ ...current, [key]: value }));
  const save = async (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); setError(''); const raw = Object.fromEntries(new FormData(e.currentTarget)); const colors = String(editing.colorsText).split('\n').map(row => { const [name, hex] = row.split('|').map(x => x.trim()); return { name, hex }; }).filter(c => c.name && /^#[0-9a-f]{6}$/i.test(c.hex)); if (!colors.length) { setError('Add at least one color using Name|#hex format.'); return; } const images = String(editing.imagesText).split('\n').map(x => x.trim()).filter(Boolean); if (!images.length) { setError('Upload at least one product image.'); return; } const body = { ...raw, price: Number(raw.price), inventory: Number(raw.inventory), published: raw.published === 'on', colorName: colors[0].name, colorHex: colors[0].hex, colors, sizes: String(editing.sizesText).split(',').map(x => x.trim()).filter(Boolean), images, tags: String(editing.tagsText).split(',').map(x => x.trim()).filter(Boolean), details: String(editing.detailsText).split('\n').map(x => x.trim()).filter(Boolean) }; const response = await fetch(`${API}/products${editing.id ? `/${editing.id}` : ''}`, { method: editing.id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!response.ok) { const data = await response.json().catch(() => ({})); setError(data.message || 'Could not save product. Check the slug is unique.'); return; } const saved = await response.json(); setItems(current => editing.id ? current.map(x => x.id === saved.id ? saved : x) : [saved, ...current]); setEditing(null); };
  const upload = async (files: FileList | null) => { if (!files?.length) return; setUploading(true); setError(''); try { const urls: string[] = []; for (const file of Array.from(files)) { const data = new FormData(); data.append('file', file); const response = await fetch(`${API}/uploads/image`, { method: 'POST', body: data }); if (!response.ok) throw new Error('Upload failed. Use JPG, PNG, WEBP, or GIF under 8MB.'); urls.push((await response.json()).url); } set('imagesText', [editing.imagesText, ...urls].filter(Boolean).join('\n')); } catch (err) { setError(err instanceof Error ? err.message : 'Upload failed'); } finally { setUploading(false); } };
  const removeImage = (url: string) => set('imagesText', String(editing.imagesText).split('\n').filter((x: string) => x.trim() !== url).join('\n'));
  const remove = async (id: string) => { if (!confirm('Delete this product permanently?')) return; const response = await fetch(`${API}/products/${id}`, { method: 'DELETE' }); if (response.ok) setItems(current => current.filter(x => x.id !== id)); };
  return <><div className="mb-5 flex items-center justify-between"><p className="text-sm font-bold">{items.length} products</p><button onClick={() => setEditing(blank)} className="rounded-full bg-ink px-5 py-3 text-xs font-bold text-white"><Plus size={15} className="mr-2 inline"/> Add product</button></div><div className="card overflow-x-auto"><table className="w-full min-w-[820px] text-left text-sm"><thead><tr className="bg-[#fafaf8] text-[10px] font-bold tracking-[.16em] text-muted uppercase"><th className="px-5 py-4">Product</th><th>Category</th><th>Price</th><th>Variants</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{items.map(p => <tr className="border-t border-line" key={p.id}><td className="px-5 py-4"><div className="flex items-center gap-3">{p.images?.[0] && <img src={p.images[0]} alt="" className="size-12 rounded-lg object-cover"/>}<div><p className="font-bold">{p.name}</p><p className="text-xs text-muted">{p.slug}</p></div></div></td><td>{p.category}</td><td>৳{p.price.toLocaleString()}</td><td className="text-xs">{p.colors?.length || 1} colors · {p.sizes?.length || 5} sizes</td><td>{p.inventory}</td><td>{p.published ? 'Published' : 'Draft'}</td><td><button onClick={() => setEditing(prepare(p))} className="mr-2 rounded border border-line p-2"><Pencil size={14}/></button><button onClick={() => remove(p.id)} className="rounded border border-red-200 p-2 text-red-600"><Trash2 size={14}/></button></td></tr>)}</tbody></table></div>{editing && <div className="fixed inset-0 z-50 grid place-items-center bg-black/45 p-4"><form onSubmit={save} className="max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-7"><div className="mb-6 flex justify-between"><div><p className="text-[10px] font-bold tracking-[.2em] text-muted uppercase">Complete product setup</p><h2 className="mt-1 text-2xl font-black">{editing.id ? 'Edit product' : 'New product'}</h2></div><button type="button" onClick={() => setEditing(null)}><X/></button></div><div className="grid gap-4 sm:grid-cols-2"><Field name="name" label="Product name" value={editing.name}/><Field name="slug" label="URL slug" value={editing.slug}/><Field name="price" label="Price (৳)" value={editing.price} type="number"/><Field name="inventory" label="Total inventory" value={editing.inventory} type="number"/><label><Label>Category</Label><select name="category" defaultValue={editing.category} className="input"><option value="acid-wash">Acid Wash</option><option value="oversized">Oversized</option><option value="essentials">Essentials</option></select></label><Field name="fabric" label="Fabric / material" value={editing.fabric}/><label className="sm:col-span-2"><Label>Available sizes · comma separated</Label><input value={editing.sizesText} onChange={e => set('sizesText', e.target.value)} className="input" placeholder="S, M, L, XL, 2XL"/><div className="mt-2 flex flex-wrap gap-2">{String(editing.sizesText).split(',').filter(Boolean).map((size:string)=><span key={size} className="rounded-md bg-[#f1f1ed] px-3 py-1 text-xs font-bold">{size.trim()}</span>)}</div></label><label className="sm:col-span-2"><Label>Colors · one per line as Name|#hex</Label><textarea value={editing.colorsText} onChange={e => set('colorsText', e.target.value)} rows={3} className="input h-auto py-3" placeholder={'Jet Black|#0b0b0b\nCloud White|#f1efe9'}/><div className="mt-2 flex flex-wrap gap-3">{String(editing.colorsText).split('\n').map((row:string)=>{const [name,hex]=row.split('|');return name&&hex?<span key={row} className="flex items-center gap-2 text-xs font-bold"><i className="size-5 rounded-full border" style={{background:hex}}/>{name}</span>:null})}</div></label><div className="sm:col-span-2"><Label>Product photos</Label><label className="flex cursor-pointer items-center justify-center gap-3 rounded-xl border-2 border-dashed border-line bg-[#fafaf8] p-6 text-sm font-bold hover:border-ink"><ImagePlus size={20}/>{uploading ? 'Uploading…' : 'Choose photos · multiple allowed'}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple disabled={uploading} onChange={e => upload(e.target.files)} className="hidden"/></label><div className="mt-3 grid grid-cols-3 gap-3 sm:grid-cols-5">{String(editing.imagesText).split('\n').filter(Boolean).map((url:string)=><div key={url} className="group relative aspect-square overflow-hidden rounded-lg bg-[#eee]"><img src={url} alt="" className="h-full w-full object-cover"/><button type="button" onClick={()=>removeImage(url)} className="absolute top-1 right-1 grid size-6 place-items-center rounded-full bg-black text-white"><X size={12}/></button></div>)}</div></div><label className="sm:col-span-2"><Label>Product badges / collections</Label><input value={editing.tagsText} onChange={e => set('tagsText', e.target.value)} className="input" placeholder="new, trending, best, must"/></label><label className="sm:col-span-2"><Label>Product detail bullets · one per line</Label><textarea value={editing.detailsText} onChange={e => set('detailsText', e.target.value)} rows={5} className="input h-auto py-3"/></label><label className="flex items-center gap-2"><input name="published" type="checkbox" defaultChecked={editing.published}/> Published on website</label></div>{error&&<p className="mt-5 rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700">{error}</p>}<button disabled={uploading} className="mt-6 w-full rounded-lg bg-ink py-4 text-xs font-bold text-white uppercase disabled:opacity-50">Save and publish product</button></form></div>}</>;
}
function Label({ children }: { children: React.ReactNode }) { return <span className="mb-2 block text-[10px] font-bold tracking-[.15em] text-muted uppercase">{children}</span>; }
function Field({ name, label, value, type = 'text' }: { name:string; label:string; value:any; type?:string }) { return <label><Label>{label}</Label><input required name={name} defaultValue={value} type={type} className="input"/></label>; }
